    /**
     * Method to retrieve the Team via TeamFetchOneSummary
     * @param 	summary TeamFetchOneSummary 
     * @return 	TeamFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Team getTeam( TeamFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "TeamFetchOneSummary arg cannot be null" );
    	
    	Team entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Team
        	// --------------------------------------
        	CompletableFuture<Team> futureEntity = queryGateway.query(new FindTeamQuery( new LoadTeamFilter( summary.getTeamId() ) ), ResponseTypes.instanceOf(Team.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Team with id " + summary.getTeamId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


